export function makeApparitionApplauseScore(condition = 'treatment', { origin = { x: 0, y: 0, z: 0 }, yaw = 0 } = {}) {
  if (!['silent', 'ordinary', 'treatment'].includes(condition)) throw new Error('Unknown applause condition: ' + condition);
  const cos = Math.cos(yaw), sin = Math.sin(yaw);
  const events = condition === 'silent' ? [] : CONFIG.people.flatMap(person => person[condition].map((time, index) => ({
    id: person.id + '-' + (index + 1), source: person.id + '-clap-' + String(index + 1).padStart(2, '0'), time,
    position: { x: origin.x + person.offset.x * cos + person.offset.z * sin, y: origin.z - person.offset.x * sin + person.offset.z * cos },
    gain: person.levels[index], dry: CONFIG.dry, wet: CONFIG.wet, impulse: condition + 'Room',
    fadeIn: 0, fadeOut: 0, playbackRate: 1, preDelay: 0,
    referenceDistance: CONFIG.referenceDistance, rolloff: CONFIG.rolloff, wetRolloff: CONFIG.wetRolloff, wetPanWidth: CONFIG.wetPanWidth,
  }))).sort((a, b) => a.time - b.time);
  return { id: CONFIG.id + ':' + condition, duration: CONFIG.duration, gain: condition === 'silent' ? 1 : APPARITION_APPLAUSE_MIX.conditions[condition].scoreGain, events };
}
